def period(name,start,end):
 out={};provenance[name]={}
 for k,t in tags.items():
  a=[x for x in facts[t]['units']['USD'] if x.get('start')==start and x['end']==end and x['filed']<='2026-11-08' and x['form'] in ['10-K','10-Q']]
  assert a,(name,k)
  x=sorted(a,key=lambda z:z['filed'])[-1];out[k]=x['val']/1e6;provenance[name][k]=dict(tag=t,**x)
 return out
h={f'FY{y}':period(f'FY{y}',f'{y}-01-01',f'{y}-12-31') for y in [2023,2024,2025]}
