for y in [2025,2026]:h[f'TTM{y}']={k:h[f'FY{y-1}'][k]+h[f'9M{y}'][k]-h[f'9M{y-1}'][k] for k in tags}
q1=period('Q12026','2026-01-01','2026-03-31');h1=period('H12026','2026-01-01','2026-06-30')
q={'Q42025':{k:h['FY2025'][k]-h['9M2025'][k] for k in tags},'Q12026':q1,'Q22026':{k:h1[k]-q1[k] for k in tags},'Q32026':{k:h['9M2026'][k]-h1[k] for k in tags}}
