pension_claim=8.5;tax_claim=9.8 # latest annual gross underfunded SERP and unrecognized tax+interest; no pension surplus monetization.
bridge=cash-reserve+investment_credit-debt-pension_claim-tax_claim
# Beginning next-full-year revenue uses mid2026 guide, excluding sold VMS and excludes pending AccuLynx. Not raw mixed-perimeter TTM.
revenue_base=3215
spec={'adverso':dict(growth=.035,margin=.425,terminal_margin=.42,wacc=.09,g=.02,roic=.14,replacement=.085,investment_intensity=.85), 'central':dict(growth=.065,margin=.455,terminal_margin=.45,wacc=.08,g=.025,roic=.20,replacement=.082,investment_intensity=.70), 'favorable':dict(growth=.085,margin=.48,terminal_margin=.47,wacc=.0725,g=.03,roic=.25,replacement=.078,investment_intensity=.55)}
def calc(s):
 rev=revenue_base;pv=0;rows=[];tax=.25
 for yr in range(1,11):
  f=max(0,(yr-5)/5);growth=s['growth']*(1-f)+s['g']*f;old=rev;rev*=1+growth;m=s['margin']*(1-f)+s['terminal_margin']*f
  nopat=rev*m*(1-tax);da_fixed=rev*.086;da_acquired=rev*.018;da=da_fixed+da_acquired
  # Cash software/physical replacement plus replacement of acquired data/customer assets. No SBC addback.
  replacement=rev*s['replacement'];intang_replace=rev*.018
  growthcap=(rev-old)*s['investment_intensity'];nwc=(rev-old)*(-.03) # limited advance-billing benefit, not full deferred revenue as free cash
  explicit=replacement+intang_replace+growthcap-da+nwc
  reinv=max(explicit,nopat*growth/s['roic']) # funded economic capital constraint also throughout fade/terminal
  fcff=nopat-reinv;pv+=fcff/(1+s['wacc'])**yr
  rows.append(dict(year=yr,revenue=rev,growth=growth,margin=m,nopat=nopat,fixed_da=da_fixed,acquired_da=da_acquired,physical_software_replacement=replacement,acquired_asset_replacement=intang_replace,growth_investment=growthcap,nwc_increase=nwc,explicit_reinvestment=explicit,funded_reinvestment=reinv,implied_total_investment=reinv+da-nwc,fcff=fcff,pv_fcff=fcff/(1+s['wacc'])**yr))
 rev11=rev*(1+s['g']);np=rev11*s['terminal_margin']*.75;da=rev11*.104;nwc=(rev11-rev)*(-.03);replacement=rev11*(s['replacement']+.018);growthcap=(rev11-rev)*s['investment_intensity'];ri=max(replacement+growthcap-da+nwc,np*s['g']/s['roic']);tv=(np-ri)/(s['wacc']-s['g']);pvt=tv/(1+s['wacc'])**10;ev=pv+pvt
 return dict(inputs=s,ev=ev,equity=ev+bridge,conditional_value_per_share=(ev+bridge)/shares,pv_explicit=pv,pv_terminal=pvt,terminal_weight=pvt/ev,terminal_fcff=np-ri,terminal_nopat=np,terminal_physical_reinvestment_floor=replacement+growthcap-da+nwc,terminal_reinvestment=ri,terminal_implied_investment=ri+da-nwc,terminal_replacement_floor=replacement,rows=rows,approved_value=None)
cases={k:calc(v) for k,v in spec.items()}
